const KEY='clinical-compass-demo-v1';
const seed={role:'patient',view:'home',reports:[],plan:null,patients:[{id:1,name:'Анастасия Александрова',initials:'АА',note:'Наблюдение · 3 недели',current:true},{id:2,name:'Мария Соколова',initials:'МС',note:'Следующий контроль 24 октября'},{id:3,name:'Илья Морозов',initials:'ИМ',note:'План подтверждён'},{id:4,name:'Елена Орлова',initials:'ЕО',note:'Ожидается самоотчёт'}]};
let state=load();
function load(){try{return {...structuredClone(seed),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return structuredClone(seed)}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function icon(n){return `<svg class="icon" aria-hidden="true"><use href="#i-${n}"></use></svg>`}
function fmtDate(x){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}).format(new Date(x))}
function latest(){return state.reports[0]||null}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),2200)}
function shell(content,active='home'){
 const doctor=state.role==='doctor';const nav=[['home','home',doctor?'Пациенты':'Главная'],['chart','progress','Динамика'],['file','plan',doctor?'Планы':'Мой план'],['message','messages','Связь'],['user','profile','Профиль']];
 return `<div class="app-shell"><aside class="desktop-sidebar"><div class="brand"><span class="brand-mark">${icon('heart')}</span><span>Клинический<br>компас</span></div><nav class="side-nav">${nav.map(([i,v,l])=>`<button class="side-link ${active===v?'active':''}" data-view="${v}">${icon(i)}<span>${l}</span></button>`).join('')}</nav><div class="side-bottom">Прототип работает на синтетических данных. Клинические решения подтверждает врач.</div></aside><main class="main"><header class="topbar"><div class="identity"><div class="avatar">${doctor?'ЕК':'А'}</div><div><p class="eyebrow">${doctor?'Кабинет врача':'Добрый день'}</p><h1>${doctor?'Елена Крылова':'Анастасия'}</h1></div></div><div class="top-actions"><button class="icon-btn" aria-label="Уведомления">${icon('bell')}${latest()&&doctor?'<i class="dot"></i>':''}</button><button class="role-switch" id="role-switch">${doctor?'Пациент':'Врач'}</button></div></header>${content}</main><nav class="bottom-nav">${nav.map(([i,v,l])=>`<button class="nav-item ${active===v?'active':''}" data-view="${v}">${icon(i)}<span>${l}</span></button>`).join('')}</nav></div>`
}
function patientHome(){const r=latest();return shell(`<section class="hero"><div class="hero-copy"><span class="badge badge-new">Ежедневная отметка</span><h2>${r?'Спасибо, отчёт уже у врача':'Как вы себя чувствуете сегодня?'}</h2><p>${r?'Можно обновить состояние, если что-то изменится.':'Это займёт меньше минуты и поможет врачу следить за вашим состоянием.'}</p><button class="btn btn-primary" data-view="report">${icon(r?'check':'plus')} ${r?'Обновить отчёт':'Заполнить отчёт'}</button></div><div class="hero-art">${icon('heart')}</div></section><section class="section"><div class="section-head"><h2>Ваше здоровье</h2></div><div class="grid quick-grid"><button class="quick-card" data-view="report"><span class="quick-icon">${icon('file')}</span><div><strong>Самоотчёт</strong><span>${r?'Передан врачу':'Ещё не заполнен'}</span></div></button><button class="quick-card" data-view="progress"><span class="quick-icon">${icon('chart')}</span><div><strong>Динамика</strong><span>Самочувствие по дням</span></div></button><button class="quick-card" data-view="plan"><span class="quick-icon">${icon('pill')}</span><div><strong>План лечения</strong><span>${state.plan?'Подтверждён врачом':'Ожидает назначения'}</span></div></button><button class="quick-card" data-view="messages"><span class="quick-icon">${icon('message')}</span><div><strong>Связь с врачом</strong><span>Задать вопрос</span></div></button></div></section><div class="content-columns"><section class="section"><div class="section-head"><h2>Сегодня</h2><button class="text-btn" data-view="progress">Подробнее</button></div><article class="card"><div class="status-line"><span class="status-orb">${icon('heart')}</span><div><strong>${r?'Состояние отмечено':'Нужна ваша отметка'}</strong><p>${r?fmtDate(r.createdAt):'Врач увидит результат сразу после отправки'}</p></div></div><div class="metric-row"><div class="metric"><b>${r?r.mood:'—'}</b><span>настроение</span></div><div class="metric"><b>${r?r.anxiety:'—'}</b><span>тревога</span></div><div class="metric"><b>${r?r.sleep:'—'}</b><span>сон</span></div></div></article></section><section class="section"><div class="section-head"><h2>Лечащий врач</h2></div><article class="card"><div class="status-line"><div class="avatar">ЕК</div><div><strong>Елена Крылова</strong><p>Терапевт · на связи</p></div></div><button class="btn btn-secondary btn-wide" data-view="messages" style="margin-top:18px">${icon('message')} Написать врачу</button></article></section></div>`,'home')}
function reportForm(){const r=latest()||{};const scale=(n,c)=>`<div class="scale">${[1,2,3,4,5].map(v=>`<input id="${n}-${v}" type="radio" name="${n}" value="${v}" ${Number(c)===v?'checked':''} required><label for="${n}-${v}">${v}</label>`).join('')}</div>`;return shell(`<div class="page-head"><button class="back" data-view="home" aria-label="Назад">${icon('chevron')}</button><h2>Самоотчёт</h2><p>Отметьте, как вы чувствуете себя сегодня</p></div><form class="form-card" id="report-form"><div class="field"><label>Настроение</label><small>1 — очень плохое, 5 — отличное</small>${scale('mood',r.mood)}</div><div class="field"><label>Уровень тревоги</label><small>1 — почти нет, 5 — очень сильная</small>${scale('anxiety',r.anxiety)}</div><div class="field"><label>Качество сна</label><small>1 — очень плохое, 5 — отличное</small>${scale('sleep',r.sleep)}</div><div class="field"><label for="comment">Что ещё важно сообщить врачу?</label><textarea id="comment" name="comment" rows="4" placeholder="Например, новые симптомы или нежелательные явления">${esc(r.comment||'')}</textarea></div><label class="check-row"><input type="checkbox" name="urgent" ${r.urgent?'checked':''}><span><b>Мне нужна срочная связь с врачом</b><br>Отметьте при резком ухудшении состояния</span></label><button class="btn btn-primary btn-wide" type="submit" style="margin-top:20px">Передать врачу ${icon('arrow')}</button></form>`,'home')}
function doctorHome(){const r=latest();return shell(`<div class="doctor-stats"><div class="stat-card"><b>4</b><span>пациента</span></div><div class="stat-card"><b>${r?'1':'0'}</b><span>новый отчёт</span></div><div class="stat-card ${r?.urgent?'alert':''}"><b>${r?.urgent?'1':'0'}</b><span>требует внимания</span></div></div><div class="doctor-layout"><section><div class="search">${icon('search')}<input id="patient-search" placeholder="Поиск пациента"></div><div class="section-head"><h2>Мои пациенты</h2><span class="badge badge-new">4 активных</span></div><div class="patient-list">${state.patients.map(p=>`<button class="patient-card" data-patient="${p.id}" data-name="${p.name.toLowerCase()}"><span class="avatar">${p.initials}</span><span><h3>${p.name}</h3><p>${p.current&&r?'Новый самоотчёт · сейчас':p.note}</p></span><span>${p.current&&r?`<i class="badge ${r.urgent?'badge-warn':'badge-new'}">${r.urgent?'Срочно':'Новый'}</i>`:icon('chevron')}</span></button>`).join('')}</div></section><section><div class="section-head"><h2>Требует внимания</h2></div>${r?`<article class="card"><div class="status-line"><div class="avatar">АА</div><div><strong>Анастасия Александрова</strong><p>Самоотчёт получен ${fmtDate(r.createdAt)}</p></div></div><div class="report-values"><div class="report-value"><b>${r.mood}</b><span>настроение</span></div><div class="report-value"><b>${r.anxiety}</b><span>тревога</span></div><div class="report-value"><b>${r.sleep}</b><span>сон</span></div></div><button class="btn btn-primary btn-wide" data-patient="1">Открыть карточку ${icon('arrow')}</button></article>`:`<article class="card empty"><span class="status-orb">${icon('check')}</span><h3>Всё спокойно</h3><p>Новых отчётов пока нет</p></article>`}</section></div>`,'home')}
function patientDetail(){const r=latest();return shell(`<div class="page-head"><button class="back" data-view="home">${icon('chevron')}</button></div><section class="card wide"><div class="detail-header"><div class="avatar">АА</div><div><h2>Анастасия Александрова</h2><p>27 лет · пациент с 30 сентября 2026</p></div></div><div class="info-strip"><span class="chip">Ведущий врач: вы</span><span class="chip">Наблюдение: 3 недели</span><span class="chip">Данные синтетические</span></div></section><div class="detail-grid section"><article class="card"><div class="section-head"><h3>Последний самоотчёт</h3>${r?'<span class="badge badge-new">Новый</span>':''}</div>${r?`<p class="eyebrow">${fmtDate(r.createdAt)}</p><div class="report-values"><div class="report-value"><b>${r.mood}/5</b><span>настроение</span></div><div class="report-value"><b>${r.anxiety}/5</b><span>тревога</span></div><div class="report-value"><b>${r.sleep}/5</b><span>сон</span></div></div>${r.comment?`<div class="notice notice-neutral"><b>Комментарий пациента</b><br>${esc(r.comment)}</div>`:''}${r.urgent?'<div class="notice" style="background:var(--danger-soft);color:#9e4147;margin-top:10px"><b>Пациент запросил срочную связь</b><br>Необходимо связаться и оценить состояние.</div>':''}`:'<div class="empty"><p>Пациент ещё не отправлял отчёт</p></div>'}</article><article class="card"><div class="section-head"><h3>План наблюдения</h3>${state.plan?'<span class="badge badge-new">Подтверждён</span>':''}</div><form id="plan-form"><div class="field"><label for="plan">Рекомендации пациенту</label><textarea id="plan" rows="7" placeholder="Введите план наблюдения...">${esc(state.plan?.text||'Продолжить ежедневные отметки самочувствия. Повторный контакт через 7 дней.')}</textarea></div><button class="btn btn-primary btn-wide" type="submit">${icon('check')} Подтвердить и отправить</button></form></article><article class="card wide"><div class="notice notice-neutral"><b>Контроль врача</b><br>План становится доступен пациенту только после явного подтверждения врачом. Автоматических назначений система не выполняет.</div></article></div>`,'home')}
function planView(){return shell(`<div class="page-head"><h2>${state.role==='doctor'?'Планы наблюдения':'Мой план'}</h2><p>${state.role==='doctor'?'Подтверждённые рекомендации пациентам':'Рекомендации вашего лечащего врача'}</p></div>${state.plan?`<article class="card plan-preview"><div class="section-head"><h3>${state.role==='doctor'?'Анастасия Александрова':'План подтверждён'}</h3><span class="badge badge-new">Актуально</span></div><p>${esc(state.plan.text)}</p><div class="notice notice-success">${icon('check')} Подтверждено врачом · ${fmtDate(state.plan.createdAt)}</div></article>`:`<article class="card empty"><span class="status-orb">${icon('file')}</span><h3>План ещё не готов</h3><p>${state.role==='doctor'?'Откройте карточку пациента, чтобы создать план.':'Врач отправит рекомендации после просмотра ваших данных.'}</p>${state.role==='doctor'?'<button class="btn btn-secondary" data-patient="1">Открыть карточку</button>':''}</article>`}`,'plan')}
function placeholder(v){const c={progress:['Динамика состояния','Здесь появятся графики повторных самоотчётов и результатов опросников.'],messages:['Связь с врачом','Защищённый канал коммуникации добавим на следующем этапе.'],profile:['Профиль','Настройки аккаунта, согласия и управление доступом.']}[v];return shell(`<div class="page-head"><h2>${c[0]}</h2><p>${c[1]}</p></div><article class="card empty"><span class="status-orb">${icon(v==='progress'?'chart':v==='messages'?'message':'user')}</span><h3>Раздел готовится</h3><p>Основа уже заложена в навигацию прототипа.</p></article>`,v)}
function esc(v){const d=document.createElement('div');d.textContent=v;return d.innerHTML}
function render(){let h;if(state.view==='report'&&state.role==='patient')h=reportForm();else if(state.view==='patient'&&state.role==='doctor')h=patientDetail();else if(state.view==='plan')h=planView();else if(['progress','messages','profile'].includes(state.view))h=placeholder(state.view);else h=state.role==='doctor'?doctorHome():patientHome();document.querySelector('#app').innerHTML=h;bind()}
function bind(){document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>{state.view=e.dataset.view;save();render();scrollTo(0,0)});document.querySelectorAll('[data-patient]').forEach(e=>e.onclick=()=>{state.view='patient';save();render();scrollTo(0,0)});document.querySelector('#role-switch')?.addEventListener('click',()=>{state.role=state.role==='patient'?'doctor':'patient';state.view='home';save();render();toast(`Открыт кабинет ${state.role==='doctor'?'врача':'пациента'}`)});document.querySelector('#report-form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);state.reports.unshift({mood:+d.get('mood'),anxiety:+d.get('anxiety'),sleep:+d.get('sleep'),comment:d.get('comment').trim(),urgent:d.get('urgent')==='on',createdAt:new Date().toISOString()});state.view='home';save();render();toast('Отчёт передан врачу')});document.querySelector('#plan-form')?.addEventListener('submit',e=>{e.preventDefault();const text=e.target.querySelector('#plan').value.trim();if(!text)return;state.plan={text,createdAt:new Date().toISOString()};save();render();toast('План подтверждён и отправлен пациенту')});document.querySelector('#patient-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.patient-card').forEach(x=>x.hidden=!x.dataset.name.includes(q))})}
render();